package kr.workbench;
import burp.api.montoya.MontoyaApi;import burp.api.montoya.http.message.requests.HttpRequest;import burp.api.montoya.http.message.responses.HttpResponse;
import javax.swing.*;import javax.swing.table.DefaultTableModel;import java.awt.*;import java.util.*;import java.util.List;import java.util.concurrent.*;import java.util.concurrent.atomic.*;
/** Scope-only response analysis; all work is passive and bounded. Repeater is explicit preparation only. */
final class ResponseReconPanel extends JPanel implements AutoCloseable {
 final MontoyaApi api;final DefaultTableModel findings=model("규칙","URL (쿼리 제외)","근거 위치","관찰 근거","관측 횟수"),documents=model("메서드","경로 템플릿","쿼리 이름","본문 이름","관찰 결과"),flowModel=model("마커","쓰기 URL","조회 URL","관찰 상태","HTTP");
 final JTable findingTable=new JTable(findings),apiTable=new JTable(documents),flowTable=new JTable(flowModel);final JLabel status=new JLabel("SCOPE 내 응답 자동 관찰 · 취약점 확정/추가 요청 없음");
 final StoredFlows flows=new StoredFlows();final LinkedHashMap<String,PassiveFindings.Finding> issues=new LinkedHashMap<>();final Map<String,Integer> counts=new HashMap<>();final Map<String,Set<String>> affected=new LinkedHashMap<>();volatile Map<String,Set<String>> displayedAffected=Map.of();final JTextArea findingDetail=new JTextArea(7,70);final LinkedHashMap<String,ApiInventory.Endpoint> inventory=new LinkedHashMap<>();final LinkedHashMap<String,Set<String>> observed=new LinkedHashMap<>();final Map<String,Set<String>> observedTemplates=new HashMap<>();
 final ThreadPoolExecutor worker=new ThreadPoolExecutor(1,1,0,TimeUnit.MILLISECONDS,new ArrayBlockingQueue<>(50),r->{Thread t=new Thread(r,"Workbench-response-recon");t.setDaemon(true);return t;});final AtomicLong generation=new AtomicLong();final AtomicBoolean closed=new AtomicBoolean();final AtomicInteger dropped=new AtomicInteger();
 final JTextField marker=new JTextField("WB_STORE_DEMO01",24),resolved=new JTextField(42);final TargetWindow markerWindow,draftWindow;ApiInventory.Endpoint drafting;volatile Map<String,ApiInventory.Endpoint> displayedInventory=Map.of();
 private static DefaultTableModel model(String... names){return new DefaultTableModel(names,0){public boolean isCellEditable(int r,int c){return false;}};}
 ResponseReconPanel(MontoyaApi api){super(new BorderLayout(8,8));this.api=api;setName("wb.response.recon");setBorder(BorderFactory.createEmptyBorder(8,8,8,8));
  markerWindow=new TargetWindow(this,"저장/조회 · 고유 마커 등록",()->{JButton register=new JButton("마커 등록");register.addActionListener(e->{try{flows.register(marker.getText().strip());status.setText("마커 등록 · 실제 쓰기/조회 요청을 관찰합니다. 요청을 자동 전송하지 않습니다.");}catch(Exception ex){status.setText(ex.getMessage());}});return TargetWindow.options(WorkbenchUi.row(new JLabel("고유 마커"),marker),new JLabel("WB_ / PR_ 접두어 · 최대 20개 · 원문 페이로드/인증값은 저장하지 않습니다."),WorkbenchUi.row(register));});
  draftWindow=new TargetWindow(this,"OpenAPI 초안 · 경로 변수 확정",()->{JButton send=new JButton("Repeater 초안 준비");send.addActionListener(e->{try{if(drafting==null)throw new IllegalArgumentException("API를 선택하세요.");if(drafting.contentType().equals("multipart/form-data"))throw new IllegalArgumentException("Multipart는 실제 트래픽을 가져와 파일 본문을 확인하세요.");var d=ApiInventory.draft(drafting,resolved.getText());HttpRequest q=HttpRequest.httpRequestFromUrl(d.url()).withMethod(d.method());if(!d.body().isEmpty())q=q.withHeader("Content-Type",drafting.contentType().isEmpty()?"application/json":drafting.contentType()).withBody(d.body());if(!WorkbenchScope.contains(api,q))throw new IllegalArgumentException("Scope 제외 · "+WorkbenchScope.reason(api,q));api.repeater().sendToRepeater(q,"OpenAPI 검토");status.setText("Repeater 초안 준비 · 인증/값/문서와 실제 메서드를 확인하세요.");}catch(Exception ex){status.setText(ex.getMessage());}});return TargetWindow.options(WorkbenchUi.row(new JLabel("확정할 URL"),resolved),new JLabel("같은 Origin · 쿼리값/인증을 복사하지 않음 · 준비는 전송/완료 처리 아님"),WorkbenchUi.row(send));});
  JButton register=new JButton("저장/조회 마커"),draft=new JButton("선택 API → Repeater 초안"),clear=new JButton("관찰 초기화");register.addActionListener(e->markerWindow.open());draft.addActionListener(e->{int row=apiTable.getSelectedRow();if(row<0){status.setText("API 항목을 선택하세요.");return;}String key=documents.getValueAt(apiTable.convertRowIndexToModel(row),0)+" "+documents.getValueAt(apiTable.convertRowIndexToModel(row),1);drafting=displayedInventory.get(key);if(drafting==null)return;resolved.setText(drafting.url());draftWindow.closeWindow();draftWindow.open();});clear.addActionListener(e->{generation.incrementAndGet();worker.getQueue().clear();submit(()->{issues.clear();counts.clear();affected.clear();inventory.clear();observed.clear();observedTemplates.clear();flows.clear();refresh(generation.get());});});
  add(WorkbenchUi.header("응답 분석","Passive 관찰 · API 문서 · 저장/조회 연결 · Scope 내 관찰만",WorkbenchUi.row(register,draft,clear)),BorderLayout.NORTH);JTabbedPane tabs=new JTabbedPane();findingDetail.setEditable(false);findingTable.getSelectionModel().addListSelectionListener(e->{if(!e.getValueIsAdjusting()){int row=findingTable.getSelectedRow();if(row>=0){int n=findingTable.convertRowIndexToModel(row);String key=ApiInventory.origin(Objects.toString(findings.getValueAt(n,1),""))+"|"+Objects.toString(findings.getValueAt(n,0),"")+"|"+Objects.toString(findings.getValueAt(n,2),"")+"|"+Objects.toString(findings.getValueAt(n,3),"");findingDetail.setText("영향 URL (쿼리 값 제외 · 그룹별 최대 100개)\n"+String.join("\n",displayedAffected.getOrDefault(key,Set.of())));}}});tabs.addTab("Passive 관찰",WorkbenchUi.split(JSplitPane.VERTICAL_SPLIT,new JScrollPane(findingTable),new JScrollPane(findingDetail),.7));tabs.addTab("API 문서",new JScrollPane(apiTable));tabs.addTab("저장/조회 연결",new JScrollPane(flowTable));add(tabs);add(status,BorderLayout.SOUTH);for(JTable table:List.of(findingTable,apiTable,flowTable)){table.setAutoCreateRowSorter(true);table.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);for(int i=0;i<table.getColumnCount();i++)table.getColumnModel().getColumn(i).setPreferredWidth(i==0?160:300);}WorkbenchUi.style(this);
 }
 void submit(Runnable task){if(closed.get())return;try{worker.execute(task);}catch(RejectedExecutionException e){dropped.incrementAndGet();}}
 void offer(HttpRequest q,HttpResponse s){if(closed.get()||q==null||s==null)return;long token=generation.get();try{if(s.body()==null||s.body().length()>2*1024*1024||!WorkbenchScope.contains(api,q))return;}catch(Exception ignored){return;}
  submit(()->{if(closed.get()||token!=generation.get())return;try{if(!WorkbenchScope.contains(api,q))return;String url=q.url(),safe=ActivityTracker.safeUrl(url);if(safe==null)return;String body=JsAnalysisPanel.readBody(s),headers=s.toString().split("\\r?\\n\\r?\\n",2)[0],type=EnvironmentResponse.header(headers,"Content-Type");
   for(var f:PassiveFindings.analyze(url,s.statusCode(),headers,body)){String key=ApiInventory.origin(safe)+"|"+f.rule()+"|"+f.location().replaceAll("Body: [0-9]+","Body")+"|"+f.evidence();if(issues.size()<500||issues.containsKey(key)){issues.put(key,f);counts.merge(key,1,(a,b)->Math.min(1000000,a+b));Set<String> urls=affected.computeIfAbsent(key,k->new LinkedHashSet<>());if(urls.size()<100)urls.add(safe);}}
   if(observed.size()>=1000&&!observed.containsKey(safe))observed.remove(observed.keySet().iterator().next());observed.computeIfAbsent(safe,k->new HashSet<>()).add(q.method());
   var docs=ApiInventory.parse(body,url);for(var e:docs)if(inventory.size()<500||inventory.containsKey(e.method()+" "+e.url()))inventory.put(e.method()+" "+e.url(),e);
   if(!docs.isEmpty()){observedTemplates.clear();for(var e:inventory.values())for(var entry:observed.entrySet())if(e.matches(entry.getKey()))observedTemplates.computeIfAbsent(e.url(),k->new HashSet<>()).addAll(entry.getValue());}
   else for(var e:inventory.values())if(e.matches(safe))observedTemplates.computeIfAbsent(e.url(),k->new HashSet<>()).add(q.method());
   String requestBody=q.body()!=null&&q.body().length()<=65536?q.bodyToString():"";flows.observe(url,q.method(),requestBody,s.statusCode(),type,body.substring(0,Math.min(body.length(),65536)));refresh(token);
  }catch(Exception e){dropped.incrementAndGet();}});
 }
 void refresh(long token){Map<String,Set<String>> affectedSnapshot=new LinkedHashMap<>();List<Object[]> fs=new ArrayList<>(),apis=new ArrayList<>(),stored=new ArrayList<>();for(var entry:issues.entrySet()){var f=entry.getValue();String group=ApiInventory.origin(f.url())+"|"+f.rule()+"|"+f.location()+"|"+f.evidence();affectedSnapshot.put(group,Set.copyOf(affected.getOrDefault(entry.getKey(),Set.of())));fs.add(new Object[]{f.rule(),f.url(),f.location(),f.evidence(),counts.get(entry.getKey())});}Map<String,Set<String>> documented=new HashMap<>();for(var e:inventory.values())documented.computeIfAbsent(e.url(),k->new HashSet<>()).add(e.method());for(var e:inventory.values()){Set<String> methods=new TreeSet<>(observedTemplates.getOrDefault(e.url(),Set.of()));methods.removeAll(documented.get(e.url()));String note=methods.isEmpty()?e.note():"문서/관측 메서드 불일치: "+String.join(",",methods);if(e.template())note+=" · 변수 미확정";apis.add(new Object[]{e.method(),e.url(),String.join(", ",new TreeSet<>(e.query())),String.join(", ",new TreeSet<>(e.body())),note});}for(var f:flows.views())stored.add(new Object[]{f.marker(),f.writeUrl(),f.readUrl(),f.state(),f.status()});Map<String,ApiInventory.Endpoint> snapshot=Map.copyOf(inventory);SwingUtilities.invokeLater(()->{if(closed.get()||token!=generation.get())return;displayedInventory=snapshot;displayedAffected=Map.copyOf(affectedSnapshot);findings.setRowCount(0);documents.setRowCount(0);flowModel.setRowCount(0);fs.forEach(findings::addRow);apis.forEach(documents::addRow);stored.forEach(flowModel::addRow);status.setText("Passive "+fs.size()+" · API "+apis.size()+" · 흐름 "+stored.size()+" · 처리 제외 "+dropped.get()+" · 관찰/후보, 취약점 확정 아님");});}
 @Override public void close(){closed.set(true);generation.incrementAndGet();worker.shutdownNow();markerWindow.close();draftWindow.close();flows.clear();}
}
